"""Explain bit unlock ordering, lost updates and acquisition."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1377': ('공용 공책을 고친 사람이 작업을 끝낸 뒤 사용 중 표시를 내려야 다음 사람이 완성된 내용을 읽을 수 있습니다. 표시를 내리는 일과 다른 작업에 차례를 넘길 수 있게 하는 일은 별도입니다.', '잠금 해제와 선점 상태 복구의 순서를 이해합니다.', '보호한 내용 수정 완료 → 잠금 비트 해제 → 이번 선점 금지 되돌리기 순서로 세 칸을 그리세요. 분석 도구용 표시는 실제 비트 변경과 다른 칸에 적으세요.', ['bit_spin_unlock은 앞서 얻은 비트 잠금을 돌려주는 함수입니다. 잠금을 얻지 못한 경우나 이미 풀어 준 경우에 다시 호출하는 것은 올바른 사용이 아닙니다. 같은 bitnum과 addr에 대응하는 잠금을 한 번 해제해야 합니다.', 'CONFIG_DEBUG_SPINLOCK이 켜져 있으면 먼저 test_bit로 잠금 표시를 읽습니다. 표시가 0이면 BUG_ON이 잘못된 상황을 드러냅니다. 일반 오류 번호를 돌려주는 검사가 아닙니다. 1이라는 확인만으로 누가 소유했는지까지 증명하지도 않습니다.', 'SMP 또는 디버그 잠금 설정이 켜져 있으면 clear_bit_unlock을 호출합니다. 잠금 비트를 0으로 바꾸며 release 순서를 제공합니다. release는 보호한 데이터의 앞선 접근을 잠금 해제 뒤로 넘기지 않도록 하는 약속입니다.', '다음 사용자가 같은 잠금을 올바른 acquire 연산으로 얻으면 이 release와 짝을 이뤄 보호한 내용을 읽는 순서를 맞춥니다. 비트를 0으로 만드는 것만 외우지 말고, 그 전에 작업한 내용과 다음 사용자의 읽기가 연결된다는 점을 함께 보세요.', '그다음 preempt_enable을 호출해 잠금 획득 때 더한 선점 금지를 되돌립니다. 선점은 다른 작업으로 CPU 실행을 바꾸는 것입니다. 이 호출이 모든 금지 상태를 무조건 0으로 만들지는 않습니다. 이전에 있던 금지는 남을 수 있습니다.', '마지막 __release(bitlock)은 분석 도구용 표시입니다. 실제 비트를 지우는 것은 앞의 clear_bit_unlock입니다. SMP와 디버그 설정이 모두 꺼지면 비트 해제 부분이 빠지므로 어느 설정의 코드를 보는지도 확인해야 합니다.'], [('비트 해제를 수행하는 경로에서 clear_bit_unlock과 preempt_enable 중 무엇이 먼저일까요?', ['preempt_enable이 항상 먼저예요', 'clear_bit_unlock이 먼저예요'], '원문은 잠금 비트를 release 방식으로 지운 다음 선점 금지를 되돌립니다. 데이터 접근 순서를 맞추는 일과 실행 차례를 바꿀 수 있게 하는 일은 역할이 다릅니다.'), ('__release(bitlock) 표시만으로 실제 잠금 비트가 지워질까요?', ['아니요. 분석 도구에 알려 주는 표시예요', '네. 이 표시가 실제 비트를 지워요'], '실제 비트 변경은 clear_bit_unlock이 담당합니다. __release는 코드의 잠금 상태를 분석하는 도구를 위한 표시이므로 실행 중의 잠금 해제 연산과 구별해야 합니다.')]), 'os1378': ('공책 한 줄을 복사해 고친 뒤 통째로 덮어쓰는 동안, 다른 사람이 그 줄의 다른 칸을 고치면 그 수정이 사라질 수 있습니다.', '약한 잠금 해제에서 같은 word의 다른 비트까지 보호해야 하는 이유를 이해합니다.', '처음 word를 0001로 쓰세요. A가 복사한 뒤 B가 1번 비트를 켜 실제 값이 0011이 됩니다. A가 옛 복사본의 0번을 지운 0000을 저장하면 B의 1도 사라진다고 적으세요.', ['__bit_spin_unlock은 이름 앞에 밑줄이 두 개 있는 별도 함수입니다. 디버그 검사와 선점 복구는 유지하지만 비트 해제에 __clear_bit_unlock을 사용합니다. 일반 bit_spin_unlock과 사용 조건이 같다고 가정하면 안 됩니다.', '여기서 word는 unsigned long 하나에 담긴 비트 묶음입니다. generic, 즉 공통 구현은 word 전체를 READ_ONCE로 읽어 old에 보관합니다. old에서 잠금 비트만 지운 뒤 그 값을 word 전체에 저장합니다.', '처음 0001에서 0번이 잠금이라고 합시다. A가 0001을 읽은 다음 B가 별도로 1번을 켜면 실제 값은 0011입니다. 하지만 A의 복사본은 여전히 0001이고 잠금 비트를 지우면 0000입니다.', 'A가 그 0000을 통째로 저장하면 B가 켠 1번도 없어집니다. 자기 복사본에서는 잠금 비트 하나만 지웠어도, 최신 저장 값의 다른 변경을 잃을 수 있는 이유입니다. 읽기와 고친 값 저장 전체가 하나의 원자적 변경은 아닙니다.', '마지막 저장은 release 순서를 제공합니다. 그렇다고 앞선 읽기까지 합쳐 하나의 원자적 읽기·수정·쓰기가 되지는 않습니다. 메모리 접근 순서의 약속과 중간에 다른 수정이 끼어들지 못하게 하는 약속은 다릅니다.', '원문은 잠금이 같은 word의 나머지 상태 비트도 보호하는 경우 등에 이 방식을 쓸 수 있다고 설명합니다. 다른 상태 비트 수정도 같은 잠금 규칙을 지켜야 합니다. 독립적으로 다른 비트를 바꾸는 코드가 있다면 그 변경을 이 저장이 보존한다고 가정하면 안 됩니다.'], [('옛 word를 읽은 뒤 다른 CPU가 다른 비트를 켜면, 옛 값으로 계산한 저장은 어떻게 될 수 있을까요?', ['다른 비트의 최신 변경을 언제나 보존해요', '다른 CPU의 변경까지 덮어쓸 수 있어요'], '예시에서 0001을 읽은 뒤 실제 값이 0011이 되어도 옛 복사본은 바뀌지 않습니다. 그 복사본으로 만든 0000을 쓰면 새로 켠 1번도 지워집니다.'), ('이 약한 해제 방식을 사용할 때 어떤 보호 조건을 확인해야 할까요?', ['같은 word의 다른 상태 비트 수정도 같은 잠금으로 보호해요', '다른 비트를 아무 때나 독립적으로 바꿔도 돼요'], '공통 구현은 word 전체의 옛 값으로 결과를 계산해 저장합니다. 같은 잠금으로 다른 상태 수정도 보호하면 예시 같은 독립 변경의 끼어들기를 막을 수 있습니다. 조건 없이 약한 해제로 바꾸면 안 됩니다.')]), 'os1379': ('사용 중이라는 표지판을 봤다고 내가 사용자라는 뜻은 아닙니다. 게다가 어떤 설정에서는 표지판 대신 다른 정보로 답하는 함수도 있습니다.', '잠금 상태 조회와 실제 소유권을 구별하고 설정별 반환을 읽습니다.', '세 줄 표를 만드세요. SMP 또는 DEBUG: 비트 읽기. 둘 다 없고 PREEMPT_COUNT: 선점 상태 값. 모두 없음: 상수 1. 어느 줄에도 내 소유자 번호는 없다고 적으세요.', ['bit_spin_is_locked는 잠금 상태를 확인하는 함수입니다. 그러나 모든 환경에서 메모리의 같은 비트를 읽는 것은 아닙니다. CONFIG는 커널을 만들 때 선택한 기능 설정을 나타냅니다.', 'CONFIG_SMP 또는 CONFIG_DEBUG_SPINLOCK이 있으면 test_bit(bitnum, addr)를 반환합니다. 지정한 비트가 켜져 있는지 읽습니다. 비트를 바꾸거나 자신에게 잠금을 주는 동작은 없습니다.', '둘 다 없고 CONFIG_PREEMPT_COUNT가 있으면 preempt_count()를 반환합니다. 이것은 현재 실행의 선점 관련 상태를 나타내는 값입니다. 특정 객체의 잠금 소유자 번호가 아니고 반드시 0 또는 1만 나오는 것도 아닙니다.', '그 설정마저 없으면 함수는 상수 1을 반환합니다. 이 경로는 addr의 비트를 읽지 않습니다. 따라서 반환 1만 보고 모든 설정에서 실제 비트가 1이라고 결론 내릴 수 없습니다.', 'SMP 경로에서 실제 비트가 1이어도 다른 CPU가 보유했을 수 있습니다. 사용 중이라는 정보와 내가 얻었다는 증거는 다릅니다. 또한 조회 후 상태가 바뀔 수 있으므로 0을 보았다는 이유만으로 보호 데이터를 마음대로 고치면 안 됩니다.', '자신의 획득 성공은 대응 lock 또는 trylock의 사용 흐름으로 확인해야 합니다. 이 조회는 설정에 맞춰 진단에 사용하고, 잠금을 얻거나 소유권을 증명하는 절차를 대신하지 않도록 읽으세요.'], [('SMP·DEBUG_SPINLOCK·PREEMPT_COUNT가 모두 없으면 무엇을 반환할까요?', ['언제나 주소의 비트를 읽은 값이에요', '상수 1이에요'], '마지막 #else 분기는 return 1입니다. 주소를 읽는 test_bit 경로와 다르므로 빌드 설정을 확인해야 합니다.'), ('SMP 경로에서 비트가 1이면 지금 호출한 작업의 잠금이라고 확신할까요?', ['아니요. 다른 CPU가 보유한 것일 수도 있어요', '네. 조회한 작업이 언제나 소유자예요'], 'test_bit는 상태 비트만 읽습니다. 그 비트에 소유자 이름이나 CPU 번호가 담겨 있지 않으므로 호출자의 소유권을 증명하지 못합니다.')]), 'os1380': ('사용 중 표시가 켜졌다면 굳이 또 예약을 시도할 필요가 없습니다. 꺼졌다면 예약을 시도할 수 있지만, 마지막 성공 여부는 실제 예약 순간에 결정됩니다.', '빠른 상태 확인과 원자적 획득의 이전 값을 구별합니다.', 'A가 0을 읽음 → B가 먼저 원자적으로 1로 바꾸고 이전 값 0을 받음 → A가 시도해 이전 값 1을 받음 순서를 적으세요. 성공자는 B입니다.', ['arch_test_and_set_bit_lock의 공통 구현은 비트를 1로 바꾸고 이전 상태를 반환하는 잠금용 연산입니다. nr은 전체 비트 번호이고 p는 저장 공간입니다. BIT_WORD로 해당 word로 이동하고 BIT_MASK로 그 안의 한 비트를 고릅니다.', '예를 들어 word가 64비트이고 nr=65라면 두 번째 word의 1번 비트를 고릅니다. 전체 word가 0인지 검사하는 것이 아니라 mask가 가리키는 비트가 켜졌는지 검사합니다.', '먼저 READ_ONCE(*p)로 읽은 값과 mask를 AND합니다. 이미 해당 비트가 1이면 즉시 1을 반환합니다. 실패할 상황에서 비싼 원자적 OR를 피하는 길입니다. READ_ONCE만으로 잠금을 얻은 것은 아닙니다.', '해당 비트가 0으로 보이면 raw_atomic_long_fetch_or_acquire를 실행합니다. OR는 그 비트를 1로 만들고 fetch는 바꾸기 전 word를 돌려준다는 뜻입니다. !!(old & mask)는 그 옛 word에서 잠금 비트만 골라 0 또는 1로 바꿉니다.', '처음 0을 읽은 뒤 다른 CPU가 먼저 잠금을 얻을 수 있습니다. 그러면 원자적 OR가 돌려준 옛 값에서는 비트가 1입니다. 최종 성공은 처음 조회가 아니라 이 원자적 연산에서 얻은 이전 비트 0으로 판단합니다.', '반환 0인 성공 경로에는 acquire 순서의 약속이 있습니다. 대응 release로 풀린 같은 잠금을 얻어 보호 데이터에 접근하는 순서를 맞추는 데 사용합니다. 반환 1인 빠른 실패 경로까지 획득했다고 해석하면 안 됩니다. 성공을 1로 알리는 bit_spin_trylock과도 반환 방향이 다릅니다.'], [('첫 조회에서 잠금 비트 0을 보았다면 원자적 OR의 이전 값도 꼭 0일까요?', ['네. 처음 본 값으로 고정돼요', '아니요. 그사이에 다른 CPU가 1로 바꿀 수 있어요'], '조회와 실제 원자적 변경은 따로 일어납니다. 다른 CPU가 먼저 획득하면 뒤의 연산은 이전 비트 1을 받아 실패합니다. 처음 조회만으로 성공을 선언하면 안 됩니다.'), ('이 원시 함수의 문서가 성공 acquire를 보장하는 반환값은 무엇일까요?', ['0이에요', '1이에요'], '반환은 이전 잠금 비트입니다. 이전 0을 1로 바꿨다면 자신이 얻었으므로 성공입니다. bit_spin_trylock의 성공 1과 혼동하지 마세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_340.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
